def magic_square_test(matrix):
    """
    Return True if matrix is a magic square.

    A magic square is treated here as a square matrix in which the sums of
    every row, every column, and both main diagonals are equal.
    """
    try:
        n = len(matrix)
        if n == 0:
            return False

        if any(len(row) != n for row in matrix):
            return False

        magic_sum = sum(matrix[0])

        for i in range(n):
            if sum(matrix[i]) != magic_sum:
                return False
            if sum(matrix[j][i] for j in range(n)) != magic_sum:
                return False

        if sum(matrix[i][i] for i in range(n)) != magic_sum:
            return False

        if sum(matrix[i][n - 1 - i] for i in range(n)) != magic_sum:
            return False

    except Exception:
        return False

    return True

