class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        windows = [set(nums[i:i + k]) for i in range(n - k + 1)]

        answer = -1

        for x in set(nums):
            count = 0
            for window in windows:
                if x in window:
                    count += 1
                    if count > 1:
                        break

            if count == 1:
                answer = max(answer, x)

        return answer
