def is_samepatterns(words, patterns):
    """
    Check whether the sequence of words follows exactly the same
    equality/difference pattern as the given patterns sequence.

    Returns True if and only if:
    - both inputs have the same length
    - equal words always correspond to equal pattern tokens
    - equal pattern tokens always correspond to equal words
    - different words correspond to different pattern tokens
    """
    if len(words) != len(patterns):
        return False

    pattern_to_word = {}
    word_to_pattern = {}

    for word, pattern in zip(words, patterns):
        if pattern in pattern_to_word:
            if pattern_to_word[pattern] != word:
                return False
        else:
            pattern_to_word[pattern] = word

        if word in word_to_pattern:
            if word_to_pattern[word] != pattern:
                return False
        else:
            word_to_pattern[word] = pattern

    return True


