def minPath(grid, k):
    if k <= 0:
        return []

    n = len(grid)
    m = len(grid[0])

    r = c = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                r, c = i, j
                break
        else:
            continue
        break

    path = [1]
    directions = ((1, 0), (-1, 0), (0, 1), (0, -1))

    for _ in range(1, k):
        best_val = None
        best_r, best_c = r, c

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                val = grid[nr][nc]
                if best_val is None or val < best_val:
                    best_val = val
                    best_r, best_c = nr, nc

        if best_val is None:
            path.append(grid[r][c])
            continue

        path.append(best_val)
        r, c = best_r, best_c

    return path
