from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        max_group = max(groups)
        INF = 10**9

        # For each possible element value, keep only its earliest index.
        first_index = [INF] * (max_group + 1)
        for idx, val in enumerate(elements):
            if val <= max_group and first_index[val] == INF:
                first_index[val] = idx

        # best[x] = smallest element index that divides x
        best = [INF] * (max_group + 1)

        for div in range(1, max_group + 1):
            idx = first_index[div]
            if idx == INF:
                continue

            for multiple in range(div, max_group + 1, div):
                if idx < best[multiple]:
                    best[multiple] = idx

        return [best[g] if best[g] != INF else -1 for g in groups]
